// ⚠️ NÃO LOGAR, NÃO PRINTAR EM OUTROS NODES

const clientId = 'be0fc69d-5057-4a1c-9e49-659c31f1c7c3';
const clientSecret = 'o5V2jk1pzk424nC2NVrU0IhLxprlfbr4';


// Junta no formato exigido pelo HTTP Basic
const raw = `${clientId}:${clientSecret}`;

// Converte para Base64
const base64 = Buffer.from(raw).toString('base64');

return [
  {
    json: {
      basicAuth: `Basic ${base64}`
    }
  }
];

const data = $('IDEAL1').item.json.body;

const total = Number(data.valor_total || 0);
const parcelas = Number(data.qtd_parcelas || 1);
const intervalo = Number(data.intervalo || 0);
const inicio = Number(data.inicia_em || 0);

const hoje = new Date();

const boletos = [];

const base = Math.floor((total / parcelas) * 100) / 100;
let soma = 0;

for (let i = 0; i < parcelas; i++) {
  let valor = base;

  if (i === parcelas - 1) {
    valor = Number((total - soma).toFixed(2));
  }

  soma += valor;

  const vencimento = new Date(hoje);

  if (parcelas === 1) {
    vencimento.setDate(vencimento.getDate() + inicio);
  } else {
    vencimento.setDate(vencimento.getDate() + inicio + (intervalo * i));
  }

  const due_date = vencimento.toISOString().split("T")[0];
  const parcela = i + 1;

  // id referência no formato P1_4_12990
  const ref = `P${parcela}${parcelas}${String(data.external_reference_id).slice(-6)}`;

  boletos.push({
    json: {
      id_int: data.external_reference_id,
      parcela: parcela,
      total_parcelas: parcelas,

      external_reference_id: ref,

      amount: valor,
      due_date: due_date,

      instructions: [
        `Parcela ${parcela}/${parcelas}`,
        `${(data.descricao || '').substring(0, 100)}`
      ],

      billing_scheme: "15",

      payer: {
        name: data.name,
        tax_id: String(data.documento || "").replace(/\D/g, ""),
        email: data.email,

        address: {
          street: data.logradouro,
          number: Number(data.numero || 0),
          complement: data.complemento,
          city: data.cidade,
          state: data.UF,
          zip_code: String(data.zip_code || "").replace(/\D/g, "")
        }
      },

      whats: data.whats || ""
    }
  });
}

return boletos;

const items = $input.all();

function limparTexto(texto) {
  if (!texto) return "";
  return texto
    .toString()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9\s]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function limitar(texto, tamanho) {
  if (!texto) return "";
  return texto.substring(0, tamanho);
}

function normalizarWhats(numero) {
  if (!numero) return "";

  let n = numero.toString().replace(/\D/g, "");
  n = n.replace(/^0+/, "");

  if (n.startsWith("55")) return n;
  return "55" + n;
}

function toBoolean(valor) {
  if (valor === true) return true;
  if (valor === false) return false;

  if (typeof valor === "string") {
    const v = valor.trim().toLowerCase();
    return v === "true" || v === "1" || v === "sim";
  }

  if (typeof valor === "number") {
    return valor === 1;
  }

  return false;
}

function ajustarExternalReferenceId(externalReferenceId, isProrrogado, isAvulso) {
  const ref = (externalReferenceId || "").toString().trim();

  if (!ref) return "";

  // remove prefixos anteriores, se houver
  let base = ref;
  if (base.startsWith("PR")) {
    base = "P" + base.substring(2);
  } else if (base.startsWith("AV")) {
    base = "P" + base.substring(2);
  }

  if (isProrrogado) {
    if (base.startsWith("P")) return "PR" + base.substring(1);
    return "PR" + base;
  }

  if (isAvulso) {
    if (base.startsWith("P")) return "AV" + base.substring(1);
    return "AV" + base;
  }

  return base;
}

return items.map(item => {
  const payer = item.json.payer || {};
  const address = payer.address || {};

  let nome = limparTexto(payer.name);
  let rua = limparTexto(address.street);
  let cidade = limparTexto(address.city);
  let complemento = limparTexto(address.complement || "");
  let estado = (address.state || "").toString().trim().toUpperCase();
  let cep = (address.zip_code || "").toString().replace(/\D/g, "");
  let numero = String(address.number ?? "0").replace(/\D/g, "") || "0";
  let email = (payer.email || "").toString().trim();
  let taxId = (payer.tax_id || "").toString().replace(/\D/g, "");
  let whats = normalizarWhats(item.json.whats || "");

  const isProrrogado = toBoolean(
    item.json.is_prorrogado ??
    item.json.body?.is_prorrogado ??
    $('IDEAL1').item.json.body?.is_prorrogado
  );

  const isAvulso = toBoolean(
    item.json.avulso ??
    item.json.is_avulso ??
    item.json.body?.avulso ??
    item.json.body?.is_avulso ??
    $('IDEAL1').item.json.body?.avulso ??
    $('IDEAL1').item.json.body?.is_avulso
  );

  const externalReferenceId = ajustarExternalReferenceId(
    item.json.external_reference_id,
    isProrrogado,
    isAvulso
  );

  nome = limitar(nome, 40);
  rua = limitar(rua, 30);
  cidade = limitar(cidade, 20);
  complemento = limitar(complemento, 20);
  estado = limitar(estado, 2);
  cep = limitar(cep, 8);
  numero = limitar(numero, 10);

  return {
    json: {
      ...item.json,
      is_prorrogado: isProrrogado,
      is_avulso: isAvulso,
      external_reference_id: externalReferenceId,
      whats: whats,
      payer: {
        ...payer,
        name: nome,
        tax_id: taxId,
        email: email,
        address: {
          ...address,
          street: rua,
          number: numero,
          complement: complemento,
          city: cidade,
          state: estado,
          zip_code: cep
        }
      }
    }
  };
});

